#!/usr/bin/env bash
# Nightly macro benchmarks on the fixed, dedicated runner (ADR 0020, task 2.6).
# Appends to bench/results/<date>-<commit>-<host>.json. Expects: an idle
# machine, the data generated by the fetch scripts, `sudo -n purge` (macOS) or
# `sudo -n tee /proc/sys/vm/drop_caches` (Linux) allowed for cold runs.
#
#   bench/scripts/nightly.sh            # full nightly
#   QUICK=1 bench/scripts/nightly.sh    # reduced sizes (sanity check of the runner)
set -euo pipefail
HERE="$(cd "$(dirname "$0")/.." && pwd)"
cd "$HERE"
export PATH="/opt/homebrew/opt/openjdk/bin:$PATH"

FEATURES="${FEATURES:-tiramemsu}"
cargo build --release --features "$FEATURES"
B="$HERE/target/release/meta-bench"
RUNS="${RUNS:-5}"
ALL="graphlava,sqlite,oxigraph,tiramemsu"
RDF="graphlava,oxigraph,tiramemsu"

if [ "${QUICK:-0}" = 1 ]; then
  S=100000; SIZES=100000,1000000; OPS=100000; LUBM=1; WD=1; BSBM=2000; SF=0.1
else
  S=10000000; SIZES=100000,1000000,10000000,100000000; OPS=100000; LUBM=100; WD=100; BSBM=28480; SF=1
fi

# Data (idempotent; generators are seeded).
[ -d data/lubm/u$LUBM ] || scripts/fetch-lubm.sh "$LUBM"
[ -d data/watdiv/sf$WD ] || scripts/fetch-watdiv.sh "$WD" || echo "WatDiv data unavailable (needs Docker)"
[ -d data/bsbm/pc$BSBM ] || scripts/fetch-bsbm.sh "$BSBM"

C=(--runs "$RUNS" --cache cold)

# Agent-memory mix: latency (open loop) and throughput (closed loop) at each durability.
for d in sync ordered relaxed; do
  "$B" mix --adapters "$ALL" --statements "$S" --ops "$OPS" --rate 2000 --durability "$d" "${C[@]}"
  "$B" mix --adapters "$ALL" --statements "$S" --ops "$OPS" --rate 0 --threads 4 --durability "$d" "${C[@]}"
done
# Versus tiramemsu: 1, 10, 100 versions per fact.
for v in 10 100; do
  "$B" mix --adapters graphlava,tiramemsu --statements 1000000 --ops "$OPS" --versions "$v" "${C[@]}"
done

# Task 2.5.
"$B" range-scan --adapters graphlava,sqlite,oxigraph --nodes "$S" "${C[@]}"
"$B" commit-latency "${C[@]}"
"$B" sweep-cost --statements "$S" --terms $((S / 10)) "${C[@]}"

# Nightly sections.
"$B" scaling --adapters graphlava,sqlite --sizes "$SIZES" --ops "$OPS" "${C[@]}"
"$B" readers --adapters graphlava,sqlite,oxigraph --statements "$S" "${C[@]}"
"$B" open-recovery --adapters "$ALL" "${C[@]}"
"$B" churn --adapters graphlava,sqlite --statements "$S" --ops $((S * 10)) "${C[@]}"

# Standard workloads and traversal.
"$B" lubm --adapters "$RDF" --universities "$LUBM" "${C[@]}"
[ -d data/watdiv/sf$WD ] && "$B" watdiv --adapters "$RDF" --scale "$WD" "${C[@]}"
"$B" bsbm --adapters "$RDF" --products "$BSBM" "${C[@]}"
"$B" snb --adapters "$RDF" --sf "$SF" "${C[@]}"

# [[17-benchmarks#Binding overhead]] for Python: per-call overhead above Rust,
# gated at +20% p50 over the stored baseline (95% bootstrap confidence).
PY="$HERE/../crates/graphlava-py"
python3 -m venv "$PY/.venv-bench"
"$PY/.venv-bench/bin/pip" -q install maturin
(cd "$PY" && VIRTUAL_ENV="$PY/.venv-bench" "$PY/.venv-bench/bin/maturin" develop --release -q)
"$PY/.venv-bench/bin/python" "$PY/bench/overhead.py" --statements "$([ "${QUICK:-0}" = 1 ] && echo 100000 || echo 1000000)" \
  --runs "$RUNS" --out "results/$(date -u +%Y%m%d)-binding-overhead-python.json" \
  --baseline results/binding-overhead-python.baseline.json
echo "nightly done: $(ls -t results/*.json | head -1)"
